actions.script:
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
level = 0; permissionEnumId = null; isOwner = false; canWrite = false; canUpload = false; viaShareId = null; drive = null
recordList = []
const currentUserId = ec.user.userId
const authzOff = ec.artifactExecution.authzDisabled()
if (!userId) userId = currentUserId
if (userId && userId !== currentUserId && !authzOff) { ec.message.addError(`The drives of user ${userId} are not yours to see`); return }
if (path != null && String(path).split('/').includes('..')) return
const row = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', driveId).one()
if (row == null) return
const repo = row.repositoryId ? ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', row.repositoryId).one() : null
const rootLocation = String(row.rootLocation || '')
const repoKind = repo ? (repo.repositoryKind || 'local') : null
const storage = rootLocation.startsWith('git:') ? 'git-' + (repoKind || 'local') : (rootLocation.startsWith('dbresource:') ? 'folder' : 'other')
const readOnly = row.driveKindEnumId === 'RdkMirror' || repoKind === 'remote' || row.archivedDate != null
drive = {driveId: row.driveId, driveName: row.driveName ?? null, description: row.description ?? null,
    driveKindEnumId: row.driveKindEnumId ?? null, rootLocation: rootLocation, repositoryId: row.repositoryId ?? null,
    ownerUserId: row.ownerUserId ?? null, quotaBytes: row.quotaBytes ?? null, archivedDate: toMillis(row.archivedDate),
    createdDate: toMillis(row.createdDate), storage: storage, readOnly: readOnly, isVersioned: storage !== 'other',
    repositoryKind: repoKind, branch: repo ? (repo.branch || 'main') : null, headCommitId: repo ? (repo.headCommitId ?? null) : null,
    remoteUrl: repo && repoKind === 'remote' ? (repo.remoteUrl ?? null) : null,
    lastFetchDate: repo ? toMillis(repo.lastFetchDate) : null, lastFetchError: repo ? (repo.lastFetchError ?? null) : null,
    fetchIntervalMinutes: repo ? (repo.fetchIntervalMinutes ?? null) : null}
const LEVELS = {RdpView: 1, RdpEdit: 2, RdpManage: 3}
if (!userId || (internal && authzOff)) {
    if (authzOff) level = 3
} else if (row.ownerUserId === userId) {
    level = 3
    isOwner = true
} else {
    let groups
    if (userId === currentUserId) {
        groups = Array.from(ec.user.getUserGroupIdSet() || [])
    } else {
        groups = Array.from(ec.entity.find('moqui.security.UserGroupMember').condition('userId', userId)
                .conditionDate('fromDate', 'thruDate', null).list()).map((member) => member.userGroupId)
        groups.push('ALL_USERS')
    }
    for (const member of ec.entity.find('moqui.resource.ResourceDriveMember').condition('driveId', driveId)
            .conditionDate('fromDate', 'thruDate', null).list()) {
        if (member.userId === userId || (member.userGroupId && groups.includes(member.userGroupId)))
            level = Math.max(level, LEVELS[member.permissionEnumId] || 1)
    }
    if (level < 2 && path != null) {
        const target = clean(path)
        const now = Number(ec.user.nowTimestamp)
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).one()
        const partyId = account ? account.partyId : null
        for (const share of ec.entity.find('moqui.resource.ResourceShare').condition('driveId', driveId).list()) {
            if (share.isLink === 'Y' || share.revokedDate != null || share.declinedDate != null) continue
            if (share.expireDate != null && toMillis(share.expireDate) <= now) continue
            const mine = share.sharedWithUserId === userId || (share.sharedWithUserGroupId && groups.includes(share.sharedWithUserGroupId))
                    || (partyId && share.sharedWithPartyId === partyId)
            if (!mine) continue
            const sharePath = clean(share.path)
            if (!(sharePath === '' || target === sharePath || target.startsWith(sharePath + '/'))) continue
            if (share.permissionEnumId === 'RspUpload') { canUpload = true; if (!viaShareId) viaShareId = share.shareId; continue }
            const shareLevel = share.permissionEnumId === 'RspEdit' ? 2 : 1
            if (shareLevel > level) { level = shareLevel; viaShareId = share.shareId }
        }
    }
}
// a records drive: below the manage level the path must be in the folder map and in records the user may see
if (row.driveKindEnumId === 'RdkRecords' && path != null) {
    const gated = level < 3 && (level > 0 || canUpload)
    let info = null
    if (!gated || userId === currentUserId) {
        info = (ec.service.sync().name('org.moqui.impl.FileServices.check#RecordPaths')
                .parameters({driveId: driveId, path: clean(path), checkVisible: gated}).call()?.pathInfoList || [])[0] || null
    }
    recordList = info ? Array.from(info.records || []) : []
    if (gated && !(info && info.visible === true)) { level = 0; canUpload = false; viaShareId = null }
}
// an external user (the framework permission EXTERNAL_USER: an app's client contacts; a failed check counts as
// external) reaches no records drive, at any level, over the screens, WebDAV or SFTP
if (row.driveKindEnumId === 'RdkRecords' && userId && (level > 0 || canUpload)
        && ec.service.sync().name('org.moqui.impl.ChatServices.get#ExternalUsers').parameter('userIdList', [userId])
            .disableAuthz().call()?.anyExternal !== false) {
    level = 0; canUpload = false; viaShareId = null; isOwner = false; recordList = []
}
permissionEnumId = [null, 'RdpView', 'RdpEdit', 'RdpManage'][level]
canWrite = level >= 2 && !readOnly
canUpload = !readOnly && (canWrite || canUpload)

const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
isRecords = false; pathInfoList = []; folderList = []
const paths = (pathList ? Array.from(pathList) : [path]).map((item) => String(item == null ? '' : item))
const drive = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', driveId).useCache(true).one()
if (drive == null || drive.driveKindEnumId !== 'RdkRecords') {
    pathInfoList = paths.map((item) => ({path: clean(item), mapped: drive != null, visible: drive != null, records: []}))
    return
}
isRecords = true
const folders = Array.from(ec.entity.find('moqui.resource.ResourceDriveRecordFolder').condition('driveId', driveId)
        .orderBy('sequenceNum').orderBy('folderPath').useCache(true).list())
        .map((row) => ({folderPath: clean(row.folderPath), recordEntityName: row.recordEntityName ?? null,
            idField: row.idField ?? null, label: row.label ?? null}))
        .filter((folder) => folder.folderPath)
folderList = folders.map((folder) => Object.assign({}, folder))
const userId = ec.user.userId
const everything = !userId && ec.artifactExecution.authzDisabled()
const shared = ec.context.sharedMap
const recordVisible = (entityName, recordId) => {
    if (everything) return true
    if (!userId || !entityName) return false
    const key = `moqui.drive.recordVisible\n${userId}\n${entityName}\n${recordId}`
    const known = shared[key]
    if (known === true || known === false) return known
    const out = ec.service.sync().name('org.moqui.impl.ChatServices.check#RecordVisible')
            .parameters({recordEntityName: entityName, recordId: recordId}).call()
    const visible = out != null && out.recordVisible === true
    shared[key] = visible
    return visible
}
for (const raw of paths) {
    // a . or .. segment is never in the map
    const parts = raw.split('/').filter((part) => part)
    const text = clean(raw)
    const segments = text ? text.split('/') : []
    let mapped = segments.length === 0 && !parts.includes('..')
    const records = []
    if (!parts.includes('..')) for (const folder of folders) {
        const pattern = folder.folderPath.split('/')
        const count = Math.min(pattern.length, segments.length)
        let matches = true
        for (let index = 0; index < count; index++) if (pattern[index] !== '*' && pattern[index] !== segments[index]) { matches = false; break }
        if (!matches) continue
        mapped = true
        if (segments.length > pattern.length && folder.recordEntityName) records.push({recordEntityName: folder.recordEntityName,
            idField: folder.idField, recordId: segments[pattern.length], folderPath: segments.slice(0, pattern.length + 1).join('/'),
            depth: pattern.length + 1})
    }
    // outermost first for the check (a record inside one the user may not see is not asked), innermost first out
    records.sort((left, right) => left.depth - right.depth)
    let visible = mapped
    if (checkVisible !== false) for (const found of records) {
        if (!visible) break
        if (!recordVisible(found.recordEntityName, found.recordId)) visible = false
    }
    records.reverse()
    pathInfoList.push({path: text, mapped: mapped, visible: visible,
        records: records.map((found) => ({recordEntityName: found.recordEntityName, idField: found.idField,
            recordId: found.recordId, folderPath: found.folderPath}))})
}

created = false
driveId = null
const currentUserId = ec.user.userId
if (!userId) userId = currentUserId
if (!userId) { ec.message.addError('No user for the personal drive'); return }
if (userId !== currentUserId && !ec.artifactExecution.authzDisabled()) { ec.message.addError(`The drive of user ${userId} is not yours`); return }
const existing = ec.entity.find('moqui.resource.ResourceDrive').condition('ownerUserId', userId)
        .condition('driveKindEnumId', 'RdkPersonal').orderBy('driveId').limit(1).list()
if (existing.length) { driveId = existing[0].driveId; return }
const root = String(ec.user.getPreference('moqui.drive.root') || 'dbresource://drive').replace(/\/+$/, '')
const row = ec.entity.makeValue('moqui.resource.ResourceDrive')
row.setSequencedIdPrimary()
const rootLocation = `${root}/personal/${userId}`
row.setFields({driveName: ec.l10n.localize('My files'), driveKindEnumId: 'RdkPersonal', rootLocation: rootLocation,
    ownerUserId: userId, createdDate: ec.user.nowTimestamp}, true, null, null)
row.create()
driveId = row.driveId
created = true
const slash = rootLocation.lastIndexOf('/')
const made = ec.resource.makeChangeSet(rootLocation.slice(0, slash)).mkdir(rootLocation.slice(slash + 1)).commit(null)
if (made.failures.length) ec.logger.warn(`Personal drive folder ${rootLocation} not made: ${made.failures[0].error}`)

const authzOff = ec.artifactExecution.authzDisabled()
const isAdmin = authzOff || ec.user.isInGroup('ADMIN')
if (!ec.user.userId && !authzOff) { ec.message.addError('No user for the drive'); return }
if (ownerUserId && ownerUserId !== ec.user.userId && !authzOff) { ec.message.addError('A drive is made for yourself'); return }
if (!ownerUserId) ownerUserId = ec.user.userId || null
const STORAGES = ['folder', 'gitDb', 'gitLocal', 'mirror']
if (!STORAGES.includes(storage)) { ec.message.addError(`Unknown drive storage ${storage}`); return }
if (storage === 'mirror' && !isAdmin) { ec.message.addError('Only an administrator adds a mirror'); return }
if (!driveKindEnumId) driveKindEnumId = storage === 'mirror' ? 'RdkMirror' : 'RdkShared'
if (driveKindEnumId === 'RdkPersonal') { ec.message.addError('A personal drive is made by ensure#PersonalDrive'); return }
if ((driveKindEnumId === 'RdkRecords' || rootLocation) && !isAdmin) { ec.message.addError('Only an administrator sets a drive location'); return }
const row = ec.entity.makeValue('moqui.resource.ResourceDrive')
row.setSequencedIdPrimary()
driveId = row.driveId
repositoryId = null
const root = String(ec.user.getPreference('moqui.drive.root') || 'dbresource://drive').replace(/\/+$/, '')
if (storage === 'folder') {
    if (!rootLocation) rootLocation = `${root}/shared/${driveId}`
} else {
    if (storage === 'mirror' && !remoteUrl) { ec.message.addError('A mirror needs the URL to fetch'); return }
    repositoryId = `DRIVE_${driveId}`
    const repo = ec.entity.makeValue('moqui.resource.GitRepository')
    repo.setFields({repositoryId: repositoryId, description: driveName, branch: branch || 'main', localPath: localPath || null,
        repositoryKind: storage === 'gitDb' ? 'db' : (storage === 'gitLocal' ? 'local' : 'remote'),
        remoteUrl: storage === 'mirror' ? remoteUrl : null, username: storage === 'mirror' ? (username || null) : null,
        accessToken: storage === 'mirror' ? (accessToken || null) : null,
        fetchIntervalMinutes: storage === 'mirror' ? (fetchIntervalMinutes ?? 60) : null}, true, null, null)
    repo.create()
    rootLocation = `git://${repositoryId}/`
}
row.setFields({driveName: driveName, description: description || null, driveKindEnumId: driveKindEnumId,
    rootLocation: rootLocation, repositoryId: repositoryId, ownerUserId: ownerUserId, quotaBytes: quotaBytes ?? null,
    createdDate: ec.user.nowTimestamp}, true, null, null)
row.create()
for (const member of Array.from(memberList || [])) {
    if (!member || (!member.userId && !member.userGroupId)) continue
    const memberRow = ec.entity.makeValue('moqui.resource.ResourceDriveMember')
    memberRow.setSequencedIdPrimary()
    memberRow.setFields({driveId: driveId, userId: member.userId || null, userGroupId: member.userGroupId || null,
        permissionEnumId: member.permissionEnumId || 'RdpView', fromDate: ec.user.nowTimestamp}, true, null, null)
    memberRow.create()
}
if (storage === 'folder' && rootLocation.startsWith('dbresource:')) {
    const slash = rootLocation.replace(/\/+$/, '').lastIndexOf('/')
    const made = ec.resource.makeChangeSet(rootLocation.slice(0, slash)).mkdir(rootLocation.replace(/\/+$/, '').slice(slash + 1)).commit(null)
    if (made.failures.length) ec.logger.warn(`Drive folder ${rootLocation} not made: ${made.failures[0].error}`)
} else if (storage === 'gitDb' || storage === 'gitLocal') {
    ec.service.sync().name('org.moqui.impl.GitServices.init#GitRepository').parameter('repositoryId', repositoryId).call()
} else if (storage === 'mirror') {
    // the first fetch in its own transaction: a failure (no network, sim mode) is recorded on the repository and
    // reported, and the drive stays; the job fetches it again
    ec.message.pushErrors()
    ec.service.sync().name('org.moqui.impl.GitServices.fetch#GitRepository').parameter('repositoryId', repositoryId)
            .requireNewTransaction(true).call()
    const fetchError = ec.message.hasError() ? ec.message.errorsString : null
    ec.message.clearErrors()
    ec.message.popErrors()
    if (fetchError) ec.message.addMessage(`The first fetch of ${remoteUrl} failed: ${fetchError}`, 'warning')
    else ec.service.sync().name('org.moqui.impl.FileServices.index#MirrorDrives').parameter('repositoryId', repositoryId).disableAuthz().call()
}

const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', driveId).call()
if (!access.drive || access.level < 1) { ec.message.addError(ec.l10n.localize('Drive not found')); return }
if (access.level < 3) { ec.message.addError(ec.l10n.localize('You may not change this drive')); return }
const row = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', driveId).one()
if (driveName) row.driveName = driveName
if (description != null) row.description = description
if (quotaBytes != null) row.quotaBytes = quotaBytes
if (clearQuota) row.quotaBytes = null
row.update()
if (access.drive.repositoryKind === 'remote' && row.repositoryId) {
    const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', row.repositoryId).one()
    if (repo) {
        if (remoteUrl) repo.remoteUrl = remoteUrl
        if (username != null) repo.username = username || null
        if (accessToken) repo.accessToken = accessToken
        if (fetchIntervalMinutes != null) repo.fetchIntervalMinutes = fetchIntervalMinutes
        repo.update()
    }
}

const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', driveId).call()
if (!access.drive || access.level < 1) { ec.message.addError(ec.l10n.localize('Drive not found')); return }
if (access.level < 3) { ec.message.addError(ec.l10n.localize('You may not change this drive')); return }
if (access.drive.driveKindEnumId === 'RdkPersonal') { ec.message.addError(ec.l10n.localize('A personal drive cannot be archived')); return }
const row = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', driveId).one()
row.archivedDate = archived === false ? null : ec.user.nowTimestamp
row.update()

driveMemberId = null
if (!userId && !userGroupId) { ec.message.addError('A member is a user or a user group'); return }
if (!['RdpView', 'RdpEdit', 'RdpManage'].includes(permissionEnumId)) { ec.message.addError(`Unknown permission ${permissionEnumId}`); return }
const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', driveId).call()
if (!access.drive || access.level < 1) { ec.message.addError(ec.l10n.localize('Drive not found')); return }
if (access.level < 3) { ec.message.addError(ec.l10n.localize('You may not change this drive')); return }
if (access.drive.driveKindEnumId === 'RdkPersonal') { ec.message.addError(ec.l10n.localize('A personal drive has no members')); return }
let find = ec.entity.find('moqui.resource.ResourceDriveMember').condition('driveId', driveId).conditionDate('fromDate', 'thruDate', null)
find = userId ? find.condition('userId', userId) : find.condition('userGroupId', userGroupId)
const existing = find.list()
if (existing.length) {
    const row = existing[0]
    row.permissionEnumId = permissionEnumId
    row.update()
    driveMemberId = row.driveMemberId
    return
}
const row = ec.entity.makeValue('moqui.resource.ResourceDriveMember')
row.setSequencedIdPrimary()
row.setFields({driveId: driveId, userId: userId || null, userGroupId: userId ? null : userGroupId,
    permissionEnumId: permissionEnumId, fromDate: ec.user.nowTimestamp}, true, null, null)
row.create()
driveMemberId = row.driveMemberId

removedCount = 0
const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', driveId).call()
if (!access.drive || access.level < 1) { ec.message.addError(ec.l10n.localize('Drive not found')); return }
if (access.level < 3) { ec.message.addError(ec.l10n.localize('You may not change this drive')); return }
let find = ec.entity.find('moqui.resource.ResourceDriveMember').condition('driveId', driveId).conditionDate('fromDate', 'thruDate', null)
if (driveMemberId) find = find.condition('driveMemberId', driveMemberId)
else if (userId) find = find.condition('userId', userId)
else if (userGroupId) find = find.condition('userGroupId', userGroupId)
else { ec.message.addError('Name the member to remove'); return }
for (const row of find.list()) {
    row.thruDate = ec.user.nowTimestamp
    row.update()
    removedCount++
}

memberList = []
const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', driveId).call()
if (!access.drive || access.level < 1) { ec.message.addError(ec.l10n.localize('Drive not found')); return }
for (const row of ec.entity.find('moqui.resource.ResourceDriveMember').condition('driveId', driveId)
        .conditionDate('fromDate', 'thruDate', null).orderBy('driveMemberId').list()) {
    let name = null
    if (row.userId) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', row.userId).one()
        name = account ? (account.userFullName || account.username) : row.userId
    } else if (row.userGroupId) {
        const group = ec.entity.find('moqui.security.UserGroup').condition('userGroupId', row.userGroupId).one()
        name = group ? (group.description || row.userGroupId) : row.userGroupId
    }
    memberList.push({driveMemberId: row.driveMemberId, userId: row.userId ?? null, userGroupId: row.userGroupId ?? null,
        name: name, permissionEnumId: row.permissionEnumId ?? null})
}

driveList = []
personalDriveId = null
const userId = ec.user.userId
if (!userId) return
personalDriveId = ec.service.sync().name('org.moqui.impl.FileServices.ensure#PersonalDrive').call().driveId
const cf = ec.entity.conditionFactory
const groups = Array.from(ec.user.getUserGroupIdSet() || [])
const memberIds = new Set()
for (const member of ec.entity.find('moqui.resource.ResourceDriveMember').condition('userId', userId)
        .conditionDate('fromDate', 'thruDate', null).list()) memberIds.add(member.driveId)
if (groups.length) for (const member of ec.entity.find('moqui.resource.ResourceDriveMember')
        .condition(cf.makeCondition('userGroupId', 'in', groups)).conditionDate('fromDate', 'thruDate', null).list()) memberIds.add(member.driveId)
const reach = [cf.makeCondition('ownerUserId', 'equals', userId)]
if (memberIds.size) reach.push(cf.makeCondition('driveId', 'in', Array.from(memberIds)))
for (const row of ec.entity.find('moqui.resource.ResourceDrive').condition(cf.makeCondition(reach, 'or')).list()) {
    if (row.archivedDate != null && !includeArchived) continue
    const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', row.driveId).call()
    if (!access.drive || access.level < 1) continue
    const drive = access.drive
    let usedBytes = null
    if (includeUsage && (drive.driveKindEnumId !== 'RdkRecords' || includeRecordsUsage)) {
        try { usedBytes = ec.resource.getTreeSize(drive.rootLocation) }
        catch (e) { ec.logger.warn(`Drive ${row.driveId} at ${drive.rootLocation} could not be sized: ${e}`) }
    }
    const memberCount = ec.entity.find('moqui.resource.ResourceDriveMember').condition('driveId', row.driveId)
            .conditionDate('fromDate', 'thruDate', null).count()
    driveList.push(Object.assign({}, drive, {level: access.level, permissionEnumId: access.permissionEnumId,
        isOwner: access.isOwner, canWrite: access.canWrite, usedBytes: usedBytes, memberCount: memberCount,
        isPersonal: drive.driveKindEnumId === 'RdkPersonal'}))
}
driveList.sort((left, right) => {
    if (left.isPersonal !== right.isPersonal) return left.isPersonal ? -1 : 1
    return String(left.driveName || '').localeCompare(String(right.driveName || '')) || String(left.driveId).localeCompare(String(right.driveId))
})

usageList = []
const ids = Array.from(new Set((driveIdList ? Array.from(driveIdList) : (driveId ? [driveId] : [])).map((id) => String(id))))
let reached = 0
for (const id of ids) {
    const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', id).call()
    if (!access.drive || access.level < 1) continue
    reached++
    if (access.drive.driveKindEnumId === 'RdkRecords' && access.level < 3) continue
    let usedBytes = null
    try { usedBytes = ec.resource.getTreeSize(access.drive.rootLocation) }
    catch (e) { ec.logger.warn(`Drive ${id} at ${access.drive.rootLocation} could not be sized: ${e}`) }
    const quota = access.drive.quotaBytes != null ? Number(access.drive.quotaBytes) : null
    usageList.push({driveId: id, usedBytes: usedBytes, quotaBytes: quota,
        usedPercent: quota && usedBytes != null ? Math.min(100, Math.round(usedBytes * 100 / quota)) : null})
}
if (driveId && !driveIdList && !reached) ec.message.addError(ec.l10n.localize('Drive not found'))

exportPath = null; exportLocation = null; fileCount = 0
const access = ec.service.sync().name('org.moqui.impl.FileServices.get#DriveAccess').parameter('driveId', driveId).call()
if (!access.drive || access.level < 1) { ec.message.addError(ec.l10n.localize('Drive not found')); return }
if (access.level < 3) { ec.message.addError(ec.l10n.localize('You may not export this drive')); return }
const drive = access.drive
if (drive.storage === 'git-db') {
    const out = ec.service.sync().name('org.moqui.impl.GitServices.export#GitRepository')
            .parameters({repositoryId: drive.repositoryId, targetPath: targetPath || null}).call()
    exportPath = out.exportPath ?? null
    fileCount = out.objectCount ?? 0
    return
}
if (drive.storage.startsWith('git-')) {
    const repo = ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', drive.repositoryId).one()
    exportPath = repo && repo.localPath ? repo.localPath : `runtime/git/${drive.repositoryId}`
    ec.message.addMessage(`Drive ${drive.driveName} is a git repository on disk: clone it from ${exportPath}`)
    return
}
const root = drive.rootLocation.replace(/\/+$/, '')
const entries = []
const walk = (folder, depth) => {
    if (depth > 32 || entries.length >= 100000) return
    for (const child of ec.resource.getChildChanges(folder ? `${root}/${folder}` : root)) {
        const path = folder ? `${folder}/${child.name}` : child.name
        if (!folder && child.name === '.trash') continue
        if (child.isFile) entries.push({path: path, location: `${root}/${path}`})
        else walk(path, depth + 1)
    }
}
walk('', 0)
exportLocation = targetLocation || `runtime://tmp/drive-export/${driveId}-${Date.now()}.zip`
const written = ec.resource.writeZip(exportLocation, entries)
fileCount = written.count
for (const failure of written.failures) ec.message.addMessage(`Not exported: ${failure.path}: ${failure.error}`, 'warning')

const clean = (text) => String(text == null ? '' : text).split('/').filter((part) => part && part !== '.').join('/')
fileList = []; folder = null; drive = null; breadcrumbList = []; moreRecordCount = 0
