        previewLocation = cached; contentType = 'image/png'
        width = info.width; height = info.height; pages = info.pages
    }
} else if (['xlsx', 'xlsm', 'xlsb', 'xls', 'ods'].includes(ext)) {
    kind = 'spreadsheet'
    contentType = fileType || null
    const ref = ec.resource.getLocationReference(`runtime://tmp/preview/${keyOf(`sheet\n${askedSheet}`)}.json`)
    let sheet = readJson(ref)
    if (sheet == null) {
        sheet = ec.resource.readSheetPreview(location, askedSheet, 100, 26)
        if (sheet != null) ref.putText(JSON.stringify(sheet))
    }
    if (sheet == null) { kind = 'none'; return }
    rows = sheet.rows; sheetNames = sheet.sheetNames; sheetName = sheet.sheetName; truncated = sheet.truncated === true
} else if (ec.resource.isTextFilename(name)) {
    kind = 'text'
    contentType = fileType || 'text/plain'
    const full = ec.resource.getLocationReference(location).getText()
    text = full == null ? null : String(full).slice(0, 4000)
}

removedCount = 0
const cutoff = Date.now() - Math.max(1, Number(maxAgeHours) || 24) * 3600000
const old = (ref) => ref.lastModified != null && Number(ref.lastModified) < cutoff
const tmp = ec.resource.getLocationReference('runtime://tmp')
if (!tmp.exists || !tmp.directory) return
// the old files under a folder, then the folder when nothing is left in it (a new, empty one stays); true when
// the folder went
const sweep = (ref, depth) => {
    let left = 0
    let removedHere = 0
    for (const child of ref.getDirectoryEntries()) {
        if (child.directory) {
            if (depth < 16 && sweep(child, depth + 1)) { removedHere++; continue }
            left++
            continue
        }
        if (old(child)) {
            try { child.delete(); removedCount++; removedHere++; continue }
            catch (e) { ec.logger.warn(`Drive temporary file ${child.location} not removed: ${e}`) }
        }
        left++
    }
    if (depth > 0 && left === 0 && (removedHere > 0 || old(ref))) {
        try { ref.delete(); return true }
        catch (e) { ec.logger.warn(`Drive temporary folder ${ref.location} not removed: ${e}`) }
    }
    return false
}
for (const folder of tmp.getDirectoryEntries()) {
    if (!folder.directory || !(['preview', 'file-text'].includes(String(folder.fileName)) || String(folder.fileName).startsWith('drive-'))) continue
    try { sweep(folder, 0) }
    catch (e) { ec.logger.warn(`Drive temporary folder ${folder.location} not cleaned: ${e}`) }
}

indexedCount = 0
removedCount = 0
if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('index#DriveFiles is internal'); return }
// the text cache key: the file and its version and size (the same in index#DriveFiles and extract#DriveFileText)
const textKey = (driveId, path, change) => ec.user.singleUseCodeHash(`${driveId}\n${path}\n${change.versionName || change.date}\n${change.size}\ntext`).replace(/[^A-Za-z0-9]/g, '').slice(0, 40)
let available = false
try { available = ec.search.isAvailable() } catch (e) { available = false }
if (!available) return
try {
    const drive = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', driveId).one()
    if (drive == null) return
    const root = String(drive.rootLocation).replace(/\/+$/, '')
    for (const removed of Array.from(removePathList || [])) {
        const text = String(removed)
        removedCount += Number(ec.search.deleteMatching({documentType: 'MoquiDriveFile', filter: {bool: {all: [
            {field: {name: 'driveId', op: 'eq', value: driveId}},
            {bool: {any: [{field: {name: 'path', op: 'eq', value: text}}, {field: {name: 'path', op: 'prefix', value: text + '/'}}]}}]}}}) || 0)
    }
    const tagNames = {}
    for (const tag of ec.entity.find('moqui.resource.ResourceTag').list()) tagNames[tag.tagId] = tag.tagName
    const tagsByPath = {}
    for (const member of ec.entity.find('moqui.resource.ResourceTagMember').condition('driveId', driveId).list())
        (tagsByPath[member.path] = tagsByPath[member.path] || []).push(member.tagId)
    const typeOf = (name, isDirectory) => {
        if (isDirectory) return 'folder'
        const ext = name.includes('.') ? name.slice(name.lastIndexOf('.') + 1).toLowerCase() : ''
        const contentType = ec.resource.contentTypeOf(name) || ''
        if (contentType.startsWith('image/')) return 'image'
        if (contentType.startsWith('video/')) return 'video'
        if (contentType.startsWith('audio/')) return 'audio'
        if (ext === 'pdf') return 'pdf'
        if (['xls', 'xlsx', 'ods', 'csv'].includes(ext)) return 'spreadsheet'
        if (['ppt', 'pptx', 'odp'].includes(ext)) return 'presentation'
        if (['doc', 'docx', 'odt', 'rtf'].includes(ext)) return 'document'
        if (['zip', 'gz', 'tgz', 'bz2', 'xz', '7z', 'rar', 'tar'].includes(ext)) return 'archive'
        if (contentType.startsWith('text/') || ['md', 'txt', 'json', 'xml', 'yaml', 'yml'].includes(ext)) return 'text'
        return 'other'
    }
    const documents = []
    const missing = []
    const textOf = (path, name, change, fileType) => {
        if (!change.isFile || !['pdf', 'spreadsheet', 'text'].includes(fileType)) return null
        const found = ec.resource.extractText(`${root}/${path}`, textKey(driveId, path, change), 100000, true)
        if (found == null && missing.length < 200) missing.push(path)
        return found ? found : null
    }
    const document = (path, change) => {
        const name = path.slice(path.lastIndexOf('/') + 1)
        const tagIds = tagsByPath[path] || []
        const fileType = typeOf(name, !change.isFile)
        documents.push({_type: 'MoquiDriveFile', _id: `${driveId}:${path}`, driveId: driveId, path: path, name: name,
            folder: path.includes('/') ? path.slice(0, path.lastIndexOf('/')) : '',
            contentType: change.isFile ? (ec.resource.contentTypeOf(name) ?? null) : null, fileType: fileType,
            isDirectory: change.isFile ? 'N' : 'Y', size: change.size ?? null,
            modifiedDate: change.date != null ? new Date(change.date).toISOString() : null, modifiedByUserId: change.userId ?? null,
            tagIds: tagIds, tags: tagIds.map((tagId) => tagNames[tagId]).filter((tagName) => tagName).join(' '),
            extractedText: textOf(path, name, change, fileType)})
    }
    const walk = (path, depth) => {
        if (documents.length >= 2000 || depth > 24) return
        for (const child of ec.resource.getChildChanges(`${root}/${path}`)) {
            if (child.name === '.gitkeep') continue
            const childPath = `${path}/${child.name}`
            document(childPath, child)
            if (!child.isFile) walk(childPath, depth + 1)
        }
    }
    for (const raw of Array.from(pathList || [])) {
        const path = String(raw).split('/').filter((part) => part && part !== '.').join('/')
        if (!path || path === '.trash' || path.startsWith('.trash/')) continue
        const change = ec.resource.getLastChange(`${root}/${path}`)
        if (change == null) continue
        document(path, change)
        if (!change.isFile) walk(path, 0)
    }
    if (documents.length) indexedCount = Number(ec.search.indexDocuments(documents)) || 0
    if (missing.length && extractMissing !== false) {
        ec.message.pushErrors()
        try {
            ec.service.async().name('org.moqui.impl.FileServices.extract#DriveFileText').parameters({driveId: driveId, pathList: missing}).call()
            if (ec.message.hasError()) ec.logger.warn(`Drive ${driveId} text of ${missing.length} files not queued: ${ec.message.errorsString}`)
        } catch (e) {
            ec.logger.warn(`Drive ${driveId} text of ${missing.length} files not queued: ${e}`)
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
    }
} catch (e) {
    ec.logger.warn(`Drive ${driveId} search documents not indexed: ${e}`)
}

extractedCount = 0
// the text cache key: the file and its version and size (the same in index#DriveFiles and extract#DriveFileText)
const textKey = (driveId, path, change) => ec.user.singleUseCodeHash(`${driveId}\n${path}\n${change.versionName || change.date}\n${change.size}\ntext`).replace(/[^A-Za-z0-9]/g, '').slice(0, 40)
const drive = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', driveId).disableAuthz().one()
if (drive == null) return
const root = String(drive.rootLocation).replace(/\/+$/, '')
const done = []
for (const raw of Array.from(pathList || []).slice(0, 200)) {
    const path = String(raw).split('/').filter((part) => part && part !== '.').join('/')
    if (!path || path.split('/').includes('..') || path === '.trash' || path.startsWith('.trash/')) continue
    try {
        const change = ec.resource.getLastChange(`${root}/${path}`)
        if (change == null || !change.isFile) continue
        ec.resource.extractText(`${root}/${path}`, textKey(driveId, path, change), 100000, false)
        extractedCount++
        done.push(path)
    } catch (e) {
        ec.logger.error(`Text of drive ${driveId} file ${path} not extracted: ${e}`)
    }
}
if (done.length) ec.service.sync().name('org.moqui.impl.FileServices.index#DriveFiles')
    .parameters({driveId: driveId, pathList: done, extractMissing: false}).disableAuthz().call()

const ids = repositoryIdList ? Array.from(repositoryIdList) : (repositoryId ? [repositoryId] : [])
for (const id of ids) {
    for (const drive of ec.entity.find('moqui.resource.ResourceDrive').condition('repositoryId', id).list()) {
        try {
            const root = String(drive.rootLocation).replace(/\/+$/, '')
            const log = ec.resource.getChangeLog(root, 2000)
            if (!log.length || log[0].versionName === drive.indexedVersionName) continue
            const changed = new Set()
            let reached = false
            for (const entry of log) {
                if (entry.versionName === drive.indexedVersionName) { reached = true; break }
                for (const changedPath of entry.paths || []) changed.add(changedPath)
            }
            const present = [], removed = []
            if (!reached && !drive.indexedVersionName) present.push(...ec.resource.getChildChanges(root).map((child) => child.name))
            else for (const changedPath of changed) (ec.resource.getLastChange(`${root}/${changedPath}`) != null ? present : removed).push(changedPath)
            ec.service.sync().name('org.moqui.impl.FileServices.index#DriveFiles').parameters({driveId: drive.driveId,
                pathList: present, removePathList: removed}).disableAuthz().call()
            drive.indexedVersionName = log[0].versionName
            drive.update()
        } catch (e) {
            ec.logger.warn(`Mirror drive ${drive.driveId} not indexed after its fetch: ${e}`)
        }
    }
}

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
valid = false
routeContext = null
if (!/^[A-Za-z0-9_-]{16,64}$/.test(String(token))) return
const shares = ec.entity.find('moqui.resource.ResourceShare').condition('linkTokenHash', ec.user.singleUseCodeHash(String(token)))
        .condition('isLink', 'Y').disableAuthz().list()
const share = shares.length === 1 ? shares[0] : null
if (share == null || share.revokedDate != null) return
if (share.expireDate != null && toMillis(share.expireDate) <= Number(ec.user.nowTimestamp)) return
valid = true
const path = String(share.path || '')
let sharerName = null
if (share.createdByUserId) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', share.createdByUserId).disableAuthz().one()
    sharerName = account ? (account.userFullName || account.username) : null
}
const drive = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', share.driveId).disableAuthz().one()
routeContext = {name: path ? path.slice(path.lastIndexOf('/') + 1) : (drive ? drive.driveName : null), isDirectory: share.isDirectory === 'Y',
    permissionEnumId: share.permissionEnumId ?? null, needsPassword: share.passwordHash != null, sharerName: sharerName,
    note: share.note ?? null, linkLabel: share.linkLabel ?? null, expireDate: toMillis(share.expireDate)}

valid = false; passwordOk = false; grant = null; share = null
const check = ec.service.sync().name('org.moqui.impl.FileServices.check#PublicShareToken').parameter('token', token).call()
if (!check.valid) { ec.message.addError(ec.l10n.localize('This link has expired or was not found')); return }
valid = true
share = check.routeContext
const row = ec.entity.find('moqui.resource.ResourceShare').condition('linkTokenHash', ec.user.singleUseCodeHash(String(token))).disableAuthz().one()
if (row.passwordHash != null) {
    if (!password || !ec.user.passwordsMatch(String(password), row.passwordHash, 'argon2')) {
        if (password) ec.message.addError(ec.l10n.localize('The password is not right'))
        return
    }
}
passwordOk = true
grant = ec.resource.makeGrant(`${row.linkTokenHash}\n${row.passwordHash || ''}`, `share:${row.shareId}`, 3600)
row.openedCount = Number(row.openedCount || 0) + 1
row.lastOpenedDate = ec.user.nowTimestamp
row.update()

fileList = []
uploadOnly = false
const check = ec.service.sync().name('org.moqui.impl.FileServices.check#PublicShareToken').parameter('token', token).call()
if (!check.valid) { ec.message.addError(ec.l10n.localize('This link has expired or was not found')); return }
const row = ec.entity.find('moqui.resource.ResourceShare').condition('linkTokenHash', ec.user.singleUseCodeHash(String(token))).disableAuthz().one()
if (row.passwordHash != null && !ec.resource.checkGrant(`${row.linkTokenHash}\n${row.passwordHash}`, `share:${row.shareId}`, grant)) {
    ec.message.addError(ec.l10n.localize('Enter the password of the link')); return
}
if (row.permissionEnumId === 'RspUpload') { uploadOnly = true; return }
const inner = String(path == null ? '' : path)
if (inner.split('/').includes('..')) { ec.message.addError(ec.l10n.localize('Not found')); return }
const relative = inner.split('/').filter((part) => part && part !== '.').join('/')
const drive = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', row.driveId).disableAuthz().one()
if (drive == null) { ec.message.addError(ec.l10n.localize('Not found')); return }
const root = String(drive.rootLocation).replace(/\/+$/, '')
const sharePath = String(row.path || '')
// a link to the whole drive does not reach its hidden trash folder
if (!sharePath && relative.split('/')[0] === '.trash') { ec.message.addError(ec.l10n.localize('Not found')); return }
const base = sharePath ? `${root}/${sharePath}` : root
if (row.isDirectory !== 'Y') {
    if (relative) { ec.message.addError(ec.l10n.localize('Not found')); return }
    const change = ec.resource.getLastChange(base)
    if (change == null) { ec.message.addError(ec.l10n.localize('Not found')); return }
    const name = sharePath.slice(sharePath.lastIndexOf('/') + 1)
    fileList.push({name: name, path: '', isDirectory: false, size: change.size ?? null, modified: change.date ?? null,
        contentType: ec.resource.contentTypeOf(name) ?? null})
    return
}
let changes
try { changes = ec.resource.getChildChanges(relative ? `${base}/${relative}` : base) }
catch (e) { ec.message.addError(ec.l10n.localize('Not found')); return }
for (const change of changes) {
    if (change.name === '.gitkeep' || (!sharePath && !relative && change.name === '.trash')) continue
    fileList.push({name: change.name, path: relative ? `${relative}/${change.name}` : change.name, isDirectory: !change.isFile,
        size: change.size ?? null, modified: change.date ?? null, contentType: change.isFile ? (ec.resource.contentTypeOf(change.name) ?? null) : null})
}
fileList.sort((left, right) => (left.isDirectory !== right.isDirectory) ? (left.isDirectory ? -1 : 1) : left.name.localeCompare(right.name))

location = null; fileName = null; contentType = null
const check = ec.service.sync().name('org.moqui.impl.FileServices.check#PublicShareToken').parameter('token', token).call()
if (!check.valid) { ec.message.addError(ec.l10n.localize('This link has expired or was not found')); return }
const row = ec.entity.find('moqui.resource.ResourceShare').condition('linkTokenHash', ec.user.singleUseCodeHash(String(token))).disableAuthz().one()
if (row.passwordHash != null && !ec.resource.checkGrant(`${row.linkTokenHash}\n${row.passwordHash}`, `share:${row.shareId}`, grant)) {
    ec.message.addError(ec.l10n.localize('Enter the password of the link')); return
}
if (row.permissionEnumId === 'RspUpload') { ec.message.addError(ec.l10n.localize('Not found')); return }
const inner = String(path == null ? '' : path)
if (inner.split('/').includes('..')) { ec.message.addError(ec.l10n.localize('Not found')); return }
const relative = inner.split('/').filter((part) => part && part !== '.').join('/')
if (relative && row.isDirectory !== 'Y') { ec.message.addError(ec.l10n.localize('Not found')); return }
const drive = ec.entity.find('moqui.resource.ResourceDrive').condition('driveId', row.driveId).disableAuthz().one()
if (drive == null) { ec.message.addError(ec.l10n.localize('Not found')); return }
const root = String(drive.rootLocation).replace(/\/+$/, '')
const sharePath = String(row.path || '')
// a link to the whole drive does not reach its hidden trash folder
if (!sharePath && relative.split('/')[0] === '.trash') { ec.message.addError(ec.l10n.localize('Not found')); return }
const base = sharePath ? `${root}/${sharePath}` : root
const target = relative ? `${base}/${relative}` : base
const change = ec.resource.getLastChange(target)
if (change == null) { ec.message.addError(ec.l10n.localize('Not found')); return }
const name = relative ? relative.slice(relative.lastIndexOf('/') + 1) : (sharePath ? sharePath.slice(sharePath.lastIndexOf('/') + 1) : drive.driveName)
if (change.isFile) {
    location = target
    fileName = name
    contentType = ec.resource.contentTypeOf(name) ?? 'application/octet-stream'
} else {
    const entries = []
    const walk = (folder, zipPath, depth) => {
        if (entries.length >= 20000 || depth > 32) return
        for (const child of ec.resource.getChildChanges(folder)) {
            if (child.name === '.gitkeep' || (folder === root && child.name === '.trash')) continue
            const childZip = zipPath ? `${zipPath}/${child.name}` : child.name
            if (child.isFile) entries.push({path: childZip, location: `${folder}/${child.name}`})
            else walk(`${folder}/${child.name}`, childZip, depth + 1)
        }
    }
    walk(target, '', 0)
    location = `runtime://tmp/drive-zip/${ec.user.randomString(16)}.zip`
    ec.resource.writeZip(location, entries)
    fileName = `${String(name).replace(/[\\/:*?"<>|]/g, '_')}.zip`
    contentType = 'application/zip'
}
if (sendResponse === true && !ec.message.hasError()) {
    const inlineOk = /^(image\/(png|jpeg|gif|webp|bmp)|application\/pdf)$/.test(String(contentType || ''))
    ec.web.sendResourceResponse(location, inline === true && inlineOk, fileName)
}

uploadedList = []
const check = ec.service.sync().name('org.moqui.impl.FileServices.check#PublicShareToken').parameter('token', token).call()
if (!check.valid) { ec.message.addError(ec.l10n.localize('This link has expired or was not found')); return }
const row = ec.entity.find('moqui.resource.ResourceShare').condition('linkTokenHash', ec.user.singleUseCodeHash(String(token))).disableAuthz().one()
if (row.passwordHash != null && !ec.resource.checkGrant(`${row.linkTokenHash}\n${row.passwordHash}`, `share:${row.shareId}`, grant)) {
    ec.message.addError(ec.l10n.localize('Enter the password of the link')); return
}
if (row.isDirectory !== 'Y' || !['RspUpload', 'RspEdit'].includes(row.permissionEnumId)) { ec.message.addError(ec.l10n.localize('This link takes no files')); return }
const inner = String(path == null ? '' : path)
if (inner.split('/').includes('..')) { ec.message.addError(ec.l10n.localize('Not found')); return }
const relative = inner.split('/').filter((part) => part && part !== '.').join('/')
if (relative && row.permissionEnumId === 'RspUpload') { ec.message.addError(ec.l10n.localize('Not found')); return }
const sharePath = String(row.path || '')
if (!sharePath && relative.split('/')[0] === '.trash') { ec.message.addError(ec.l10n.localize('Not found')); return }
const folder = [sharePath, relative].filter((part) => part).join('/')
const who = String(uploaderName || '').trim().slice(0, 100)
const out = ec.service.sync().name('org.moqui.impl.FileServices.upload#Resource').parameters({driveId: row.driveId, path: folder,
    fileList: fileList ?? null, file: file ?? null, conflictPolicy: 'keepBoth', asInternal: true,
    versionNote: who ? `Uploaded by ${who} through a link` : 'Uploaded through a link'}).disableAuthz().call()
uploadedList = (out.uploadedList || []).map((item) => ({name: item.name, outcome: item.outcome, error: item.error ?? null,
    path: item.path && sharePath && String(item.path).startsWith(sharePath + '/') ? String(item.path).slice(sharePath.length + 1) : (sharePath ? null : item.path)}))
